UPDATE standard.dictionary_entry SET stts_cd=#{state},lck_ver_no=lck_ver_no+1,mdfcn_dt=CURRENT_TIMESTAMP,
    sbmsn_user_id=CASE WHEN #{state}='IN_REVIEW' THEN CAST(#{actor} AS uuid) ELSE sbmsn_user_id END,
    dcsn_user_id=CASE WHEN #{state} IN ('APPROVED','REJECTED') THEN CAST(#{actor} AS uuid) ELSE dcsn_user_id END,dcsn_rsn=#{reason}
    WHERE id=CAST(#{id} AS uuid) AND stts_cd=#{oldState} AND lck_ver_no=#{version}
